import{_ as a,o as i,c as l,ag as t}from"./chunks/framework.DQQHyi2x.js";const h=JSON.parse('{"title":"Agent Team Presets Implementation Plan","description":"","frontmatter":{},"headers":[],"relativePath":"plans/agent-mail/2026-06-15-agent-team-presets-implementation-plan.md","filePath":"plans/agent-mail/2026-06-15-agent-team-presets-implementation-plan.md"}'),o={name:"plans/agent-mail/2026-06-15-agent-team-presets-implementation-plan.md"};function n(s,e,r,d,c,u){return i(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="agent-team-presets-implementation-plan" tabindex="-1">Agent Team Presets Implementation Plan <a class="header-anchor" href="#agent-team-presets-implementation-plan" aria-label="Permalink to &quot;Agent Team Presets Implementation Plan&quot;">​</a></h1><p>Date: 2026-06-15 Issue: <a href="https://github.com/adrirubio/claude-deck/issues/189" target="_blank" rel="noreferrer">https://github.com/adrirubio/claude-deck/issues/189</a> Branch: <code>feat/agent-team-presets-189</code></p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Agent Team Presets let a Claude Deck user save reusable agent rosters such as <code>DevOps</code>, <code>Project A</code>, or <code>Project B</code>, then launch the needed Claude Code and Codex sessions with one action.</p><p>This feature should be a practical orchestration layer over existing systems:</p><ul><li>Agent Bridge owns tmux session discovery, terminal access, and provider-specific spawning.</li><li>Agent Mail owns local agent identity, inboxes, roles, charters, context requests, and handoffs.</li><li>Agent Team Presets own desired rosters, launch planning, and per-team slot context.</li></ul><p>The feature should not introduce a second messaging model. It should make it easier to create the right local team, then continue using Agent Mail for communication.</p><h2 id="product-principles" tabindex="-1">Product Principles <a class="header-anchor" href="#product-principles" aria-label="Permalink to &quot;Product Principles&quot;">​</a></h2><ol><li><strong>Launch useful teams, not gimmicks.</strong> A preset is valuable only if it reliably brings up the right agents with the right repository and operating context.</li><li><strong>Prefer reconciliation over blind spawning.</strong> Deck should inspect live sessions and reuse matching agents before creating new tmux sessions.</li><li><strong>Keep global repo identity stable.</strong> Agent Mail currently models one durable member per repo. Team presets must not overwrite global member role/charter every time a preset launches.</li><li><strong>Make launch state inspectable.</strong> The user should see which slots are already running, which will be spawned, which are pending registration, and which failed.</li><li><strong>Stay provider-aware.</strong> Claude Code and Codex launch options differ. The preset model should store common slot intent plus provider-specific launch options.</li><li><strong>Do not hide setup prerequisites.</strong> If Agent Mail MCP/hooks are missing for a provider, the launch plan should say so before spawning.</li><li><strong>Support agent-friendly orchestration.</strong> The UI is one caller, not the only caller. Local external agents and scripts should be able to plan and launch presets through stable JSON APIs.</li></ol><h2 id="supported-use-cases" tabindex="-1">Supported Use Cases <a class="header-anchor" href="#supported-use-cases" aria-label="Permalink to &quot;Supported Use Cases&quot;">​</a></h2><h3 id="uc1-save-a-project-team" tabindex="-1">UC1: Save A Project Team <a class="header-anchor" href="#uc1-save-a-project-team" aria-label="Permalink to &quot;UC1: Save A Project Team&quot;">​</a></h3><p>The user creates a <code>Project A</code> team with slots:</p><ul><li><code>Backend owner</code>: Codex in <code>/repos/project-a-api</code></li><li><code>Frontend owner</code>: Claude Code in <code>/repos/project-a-web</code></li><li><code>DevOps</code>: Codex in <code>/repos/project-a-infra</code></li></ul><p>The user can later launch this team from Deck and get the same structure back.</p><p>Supported in v1:</p><ul><li>create/edit/delete preset</li><li>create/edit/delete/reorder slots</li><li>store provider, repo path, role, charter, launch mode, and provider options</li><li>launch all enabled slots</li></ul><h3 id="uc2-reuse-already-running-agents" tabindex="-1">UC2: Reuse Already-Running Agents <a class="header-anchor" href="#uc2-reuse-already-running-agents" aria-label="Permalink to &quot;UC2: Reuse Already-Running Agents&quot;">​</a></h3><p>The user already has a Codex tmux session running in <code>/repos/project-a-api</code>. Launching <code>Project A</code> should mark the backend slot as reused instead of spawning another backend session.</p><p>Supported in v1:</p><ul><li>compare desired slot provider + repo path against Agent Bridge tmux discovery</li><li>show <code>Reused</code> in launch plan/result</li><li>avoid duplicate sessions by default</li></ul><p>Deferred:</p><ul><li>fuzzy matching across moved/renamed repositories beyond normalized repo root/path</li><li>attaching a team slot to a non-tmux session that cannot be observed</li></ul><h3 id="uc3-spawn-missing-agents" tabindex="-1">UC3: Spawn Missing Agents <a class="header-anchor" href="#uc3-spawn-missing-agents" aria-label="Permalink to &quot;UC3: Spawn Missing Agents&quot;">​</a></h3><p>The user launches <code>Project A</code>; the frontend slot is missing. Deck starts a new tmux session using the existing Agent Bridge spawn service.</p><p>Supported in v1:</p><ul><li>spawn missing slots through <code>spawn_session</code></li><li>pass provider-specific options through the existing <code>SpawnCommandOptions</code></li><li>return per-slot result instead of failing the entire launch when one slot fails</li></ul><h3 id="uc4-bootstrap-agents-into-the-correct-team-context" tabindex="-1">UC4: Bootstrap Agents Into The Correct Team Context <a class="header-anchor" href="#uc4-bootstrap-agents-into-the-correct-team-context" aria-label="Permalink to &quot;UC4: Bootstrap Agents Into The Correct Team Context&quot;">​</a></h3><p>When a launched agent starts, it should understand the team and slot it belongs to.</p><p>Supported in v1:</p><ul><li>spawn sessions with environment variables: <ul><li><code>CLAUDE_DECK_TEAM_PRESET_ID</code></li><li><code>CLAUDE_DECK_TEAM_SLOT_ID</code></li></ul></li><li>include a bootstrap prompt when possible: <ul><li>&quot;You are joining Claude Deck team Project A as Backend owner. Call <code>deck_whoami</code>, then wait for direction.&quot;</li></ul></li><li>have MCP/hook registration forward team env values to Agent Mail session metadata</li><li>have Agent Mail context include slot role/charter when the active session has a slot</li></ul><h3 id="uc5-create-a-preset-from-current-agent-mail-roster" tabindex="-1">UC5: Create A Preset From Current Agent Mail Roster <a class="header-anchor" href="#uc5-create-a-preset-from-current-agent-mail-roster" aria-label="Permalink to &quot;UC5: Create A Preset From Current Agent Mail Roster&quot;">​</a></h3><p>The user has a useful set of currently registered Agent Mail members and wants to save it as a preset.</p><p>Supported in v1:</p><ul><li><code>Create from current roster</code></li><li>each selected Agent Mail member becomes one slot</li><li>default provider inferred from best live session when possible</li><li>default role/charter copied from the current member values into slot role/charter</li></ul><p>Important behavior:</p><ul><li>copying member role/charter into slot role/charter is a snapshot, not a live binding</li><li>later editing the preset does not mutate global Agent Mail member role/charter</li></ul><h3 id="uc6-devops-or-cross-project-team" tabindex="-1">UC6: DevOps Or Cross-Project Team <a class="header-anchor" href="#uc6-devops-or-cross-project-team" aria-label="Permalink to &quot;UC6: DevOps Or Cross-Project Team&quot;">​</a></h3><p>The user defines a team whose repos are loosely related, such as <code>DevOps</code> with infrastructure, deployment, monitoring, and app repos.</p><p>Supported in v1:</p><ul><li>slots can point to arbitrary local repo paths</li><li>slots do not need to share a common parent project</li><li>Agent Mail can still route between the resulting repo members</li></ul><h3 id="uc7-edit-team-roster-without-launching" tabindex="-1">UC7: Edit Team Roster Without Launching <a class="header-anchor" href="#uc7-edit-team-roster-without-launching" aria-label="Permalink to &quot;UC7: Edit Team Roster Without Launching&quot;">​</a></h3><p>The user can maintain a preset as a durable roster without spawning anything yet.</p><p>Supported in v1:</p><ul><li>create/edit/delete slots without side effects</li><li>disabled slots stay in the preset but are excluded from launch by default</li><li>validation errors are shown inline</li></ul><h3 id="uc8-inspect-launch-outcome" tabindex="-1">UC8: Inspect Launch Outcome <a class="header-anchor" href="#uc8-inspect-launch-outcome" aria-label="Permalink to &quot;UC8: Inspect Launch Outcome&quot;">​</a></h3><p>After launching, the user should know what happened.</p><p>Supported in v1:</p><ul><li>launch result includes one item per slot</li><li>item states: <ul><li><code>reused</code></li><li><code>spawned</code></li><li><code>pending_registration</code></li><li><code>failed</code></li><li><code>skipped_disabled</code></li><li><code>blocked_provider_unavailable</code></li><li><code>blocked_agent_mail_not_configured</code></li></ul></li><li>result includes tmux target/session name when available</li><li>result includes error message when failed</li></ul><h3 id="uc9-launch-a-single-slot" tabindex="-1">UC9: Launch A Single Slot <a class="header-anchor" href="#uc9-launch-a-single-slot" aria-label="Permalink to &quot;UC9: Launch A Single Slot&quot;">​</a></h3><p>The user wants only the DevOps slot, not the whole team.</p><p>Supported in v1:</p><ul><li>per-slot launch action uses the same launch planner and result model</li><li>still reuses matching live sessions by default</li></ul><h3 id="uc10-external-agent-launches-a-team-preset" tabindex="-1">UC10: External Agent Launches A Team Preset <a class="header-anchor" href="#uc10-external-agent-launches-a-team-preset" aria-label="Permalink to &quot;UC10: External Agent Launches A Team Preset&quot;">​</a></h3><p>An external local agent, such as an OpenClaw instance or another orchestrator running on the user&#39;s machine, wants to launch a known Claude Deck team before delegating work to its members.</p><p>Supported in v1:</p><ul><li>CRUD, launch-plan, and launch endpoints return stable machine-readable JSON</li><li>launch planning does not require browser state</li><li>launch execution can be called through the HTTP API by a local external agent</li><li>external callers get the same per-slot statuses as the UI</li><li>external callers can request a dry-run plan, inspect it, then submit the returned <code>plan_hash</code> to launch</li></ul><p>Important boundaries:</p><ul><li>this is not autonomous scheduling; the external agent is an explicit caller</li><li>this does not require new cross-machine auth or remote exposure in v1</li><li>the API should remain localhost-oriented unless a broader external-control security design is added later</li></ul><h2 id="explicitly-unsupported-or-deferred-use-cases" tabindex="-1">Explicitly Unsupported Or Deferred Use Cases <a class="header-anchor" href="#explicitly-unsupported-or-deferred-use-cases" aria-label="Permalink to &quot;Explicitly Unsupported Or Deferred Use Cases&quot;">​</a></h2><h3 id="multiple-independently-addressable-agents-in-the-same-repo" tabindex="-1">Multiple Independently Addressable Agents In The Same Repo <a class="header-anchor" href="#multiple-independently-addressable-agents-in-the-same-repo" aria-label="Permalink to &quot;Multiple Independently Addressable Agents In The Same Repo&quot;">​</a></h3><p>Agent Mail currently uses one durable member per repo, so multiple sessions in the same repo share one inbox and identity.</p><p>V1 stance:</p><ul><li>allow at most one enabled slot per normalized repo path in a preset by default</li><li>if later allowed, the UI must warn that same-repo slots share an Agent Mail inbox</li></ul><p>Deferred:</p><ul><li>multi-member-per-repo Agent Mail identities</li><li>addressing a message to a specific same-repo session/slot</li></ul><h3 id="non-tmux-wakeability" tabindex="-1">Non-Tmux Wakeability <a class="header-anchor" href="#non-tmux-wakeability" aria-label="Permalink to &quot;Non-Tmux Wakeability&quot;">​</a></h3><p>Team presets should not solve non-tmux wakeability.</p><p>V1 stance:</p><ul><li>launching creates tmux sessions through Agent Bridge</li><li>reuse only counts observable tmux sessions for wakeable launch state</li><li>non-tmux sessions may still register through MCP, but are not reliable launch/reuse targets</li></ul><h3 id="cross-machine-teams" tabindex="-1">Cross-Machine Teams <a class="header-anchor" href="#cross-machine-teams" aria-label="Permalink to &quot;Cross-Machine Teams&quot;">​</a></h3><p>V1 is local-machine only.</p><p>Deferred:</p><ul><li>remote hosts</li><li>distributed Deck instances</li><li>cloud-hosted agent teams</li></ul><h3 id="autonomous-scheduling" tabindex="-1">Autonomous Scheduling <a class="header-anchor" href="#autonomous-scheduling" aria-label="Permalink to &quot;Autonomous Scheduling&quot;">​</a></h3><p>V1 is explicitly launched by a caller. That caller can be the Deck UI, a local script, or a local external agent using the HTTP API.</p><p>Deferred:</p><ul><li>scheduled team launch</li><li>recurring maintenance runs</li><li>automatic launch based on GitHub events</li></ul><p>Do not implement the launch API in a way that depends on browser-only state, modal-only confirmation, or UI-only tokens. The UI may use the same API, but external local agents must be able to call the API intentionally.</p><h3 id="full-team-lifecycle-management" tabindex="-1">Full Team Lifecycle Management <a class="header-anchor" href="#full-team-lifecycle-management" aria-label="Permalink to &quot;Full Team Lifecycle Management&quot;">​</a></h3><p>V1 focuses on launch and visibility.</p><p>Deferred unless cheap:</p><ul><li>stop all sessions for team</li><li>restart all sessions</li><li>cleanup worktrees</li><li>preserve launch history indefinitely</li></ul><h2 id="current-codebase-facts" tabindex="-1">Current Codebase Facts <a class="header-anchor" href="#current-codebase-facts" aria-label="Permalink to &quot;Current Codebase Facts&quot;">​</a></h2><p>Agent Bridge already provides:</p><ul><li><code>backend/app/services/agent_bridge/spawn.py</code><ul><li>validates directories</li><li>spawns tmux sessions</li><li>delegates command construction to provider modules</li></ul></li><li><code>backend/app/api/v1/agent_bridge/router.py</code><ul><li><code>POST /api/v1/agent-bridge/sessions</code></li><li><code>GET /api/v1/agent-bridge/sessions</code></li></ul></li><li>provider launch options in <code>SpawnCommandOptions</code></li><li>provider implementations: <ul><li><code>ClaudeCodeProvider</code></li><li><code>CodexCliProvider</code></li></ul></li></ul><p>Agent Mail already provides:</p><ul><li>durable <code>MailTeamMember</code>, keyed by repo identity</li><li>ephemeral <code>MailAgentSession</code></li><li>member role/charter editing</li><li>MCP/hook registration</li><li>tmux wakeability for observed Codex sessions</li><li>context injection through <code>build_session_start_context</code> and prompt submit context</li></ul><p>Gaps:</p><ul><li>no saved roster model</li><li>no launch planning or reconciliation</li><li>no per-team/per-slot context overlay</li><li>no UI for saved teams</li><li>no durable launch result model</li></ul><h2 id="proposed-architecture" tabindex="-1">Proposed Architecture <a class="header-anchor" href="#proposed-architecture" aria-label="Permalink to &quot;Proposed Architecture&quot;">​</a></h2><p>Add a new feature area named <code>agent-teams</code>.</p><p>Backend modules:</p><ul><li><code>backend/app/services/agent_team_service.py</code></li><li><code>backend/app/api/v1/agent_teams.py</code></li><li>schema additions in <code>backend/app/models/schemas.py</code></li><li>database models in <code>backend/app/models/database.py</code></li></ul><p>Frontend modules:</p><ul><li><code>frontend/src/features/agent-teams/AgentTeamsPage.tsx</code></li><li><code>frontend/src/features/agent-teams/api.ts</code></li><li><code>frontend/src/features/agent-teams/types.ts</code></li><li>supporting components: <ul><li><code>PresetList</code></li><li><code>PresetEditor</code></li><li><code>SlotEditor</code></li><li><code>LaunchPlanDialog</code></li><li><code>LaunchResultPanel</code></li></ul></li></ul><p>Navigation:</p><ul><li>Add <code>Agent Teams</code> under Operations, near Agent Mail.</li><li>Keep Agent Mail focused on communication.</li></ul><h2 id="data-model" tabindex="-1">Data Model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data Model&quot;">​</a></h2><h3 id="agent-team-presets" tabindex="-1"><code>agent_team_presets</code> <a class="header-anchor" href="#agent-team-presets" aria-label="Permalink to &quot;`agent_team_presets`&quot;">​</a></h3><p>Fields:</p><ul><li><code>id</code></li><li><code>name</code></li><li><code>description</code></li><li><code>is_archived</code></li><li><code>created_at</code></li><li><code>updated_at</code></li></ul><p>Notes:</p><ul><li><code>name</code> should be unique among non-archived presets.</li><li>hard delete is acceptable for v1 if no launch history references it; otherwise use archive.</li></ul><h3 id="agent-team-slots" tabindex="-1"><code>agent_team_slots</code> <a class="header-anchor" href="#agent-team-slots" aria-label="Permalink to &quot;`agent_team_slots`&quot;">​</a></h3><p>Fields:</p><ul><li><code>id</code></li><li><code>preset_id</code></li><li><code>position</code></li><li><code>enabled</code></li><li><code>display_name</code></li><li><code>provider</code></li><li><code>repo_path</code></li><li><code>repo_id</code></li><li><code>repo_name</code></li><li><code>role</code></li><li><code>charter</code></li><li><code>launch_mode</code></li><li><code>launch_options</code> JSON</li><li><code>bootstrap_prompt</code></li><li><code>created_at</code></li><li><code>updated_at</code></li></ul><p><code>launch_options</code> should store provider-specific options already supported by Agent Bridge:</p><ul><li>Claude Code: <ul><li><code>mode</code></li><li><code>worktree_name</code></li><li><code>skip_permissions</code></li><li><code>platform</code></li><li><code>aws_region</code></li><li><code>aws_profile</code></li><li><code>bedrock_model</code></li></ul></li><li>Codex: <ul><li><code>mode</code></li><li><code>model</code></li><li><code>profile</code></li><li><code>profile_v2</code></li><li><code>sandbox</code></li><li><code>approval_policy</code></li><li><code>search</code></li><li><code>no_alt_screen</code></li><li><code>dangerously_bypass_approvals_and_sandbox</code></li><li><code>use_last</code></li><li><code>session_id</code></li></ul></li></ul><p>Validation:</p><ul><li><code>repo_path</code> must be absolute and exist at save time.</li><li>derive <code>repo_id</code>/<code>repo_name</code> using existing repo identity helper.</li><li>provider must be known.</li><li>launch mode must be supported by provider.</li><li>v1 should reject duplicate enabled slots with the same <code>repo_id</code> inside one preset.</li></ul><h3 id="agent-team-launches" tabindex="-1"><code>agent_team_launches</code> <a class="header-anchor" href="#agent-team-launches" aria-label="Permalink to &quot;`agent_team_launches`&quot;">​</a></h3><p>Fields:</p><ul><li><code>id</code></li><li><code>preset_id</code></li><li><code>status</code></li><li><code>started_at</code></li><li><code>finished_at</code></li><li><code>summary</code> JSON</li></ul><p>Launch status:</p><ul><li><code>planning</code></li><li><code>running</code></li><li><code>completed</code></li><li><code>partial_failure</code></li><li><code>failed</code></li></ul><h3 id="agent-team-launch-items" tabindex="-1"><code>agent_team_launch_items</code> <a class="header-anchor" href="#agent-team-launch-items" aria-label="Permalink to &quot;`agent_team_launch_items`&quot;">​</a></h3><p>Fields:</p><ul><li><code>id</code></li><li><code>launch_id</code></li><li><code>slot_id</code></li><li><code>status</code></li><li><code>provider</code></li><li><code>repo_path</code></li><li><code>tmux_target</code></li><li><code>session_name</code></li><li><code>message</code></li><li><code>error</code></li><li><code>started_at</code></li><li><code>finished_at</code></li></ul><p>This table can be optional for v1 if the implementation returns transient launch results. Prefer adding it if it is not too much overhead because it makes support and UI easier.</p><h3 id="mail-agent-sessions-extension" tabindex="-1"><code>mail_agent_sessions</code> Extension <a class="header-anchor" href="#mail-agent-sessions-extension" aria-label="Permalink to &quot;`mail_agent_sessions` Extension&quot;">​</a></h3><p>Add optional fields:</p><ul><li><code>team_preset_id</code></li><li><code>team_slot_id</code></li></ul><p>These fields describe the team context of a particular session. They do not change the durable repo member identity.</p><h2 id="backend-api" tabindex="-1">Backend API <a class="header-anchor" href="#backend-api" aria-label="Permalink to &quot;Backend API&quot;">​</a></h2><h3 id="presets-crud" tabindex="-1">Presets CRUD <a class="header-anchor" href="#presets-crud" aria-label="Permalink to &quot;Presets CRUD&quot;">​</a></h3><ul><li><code>GET /api/v1/agent-teams/presets</code></li><li><code>POST /api/v1/agent-teams/presets</code></li><li><code>GET /api/v1/agent-teams/presets/{preset_id}</code></li><li><code>PATCH /api/v1/agent-teams/presets/{preset_id}</code></li><li><code>DELETE /api/v1/agent-teams/presets/{preset_id}</code></li><li><code>POST /api/v1/agent-teams/presets/{preset_id}/duplicate</code></li></ul><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><p>Either nest slots inside preset update payloads or provide explicit endpoints:</p><ul><li><code>POST /api/v1/agent-teams/presets/{preset_id}/slots</code></li><li><code>PATCH /api/v1/agent-teams/slots/{slot_id}</code></li><li><code>DELETE /api/v1/agent-teams/slots/{slot_id}</code></li><li><code>POST /api/v1/agent-teams/presets/{preset_id}/slots/reorder</code></li></ul><p>For v1, nested updates are simpler only if the editor saves the whole preset at once. Explicit endpoints are better for incremental UI and validation.</p><h3 id="create-from-agent-mail" tabindex="-1">Create From Agent Mail <a class="header-anchor" href="#create-from-agent-mail" aria-label="Permalink to &quot;Create From Agent Mail&quot;">​</a></h3><ul><li><code>POST /api/v1/agent-teams/presets/from-agent-mail</code></li></ul><p>Request:</p><ul><li><code>name</code></li><li>optional <code>member_ids</code></li><li>optional <code>include_offline</code></li></ul><p>Behavior:</p><ul><li>read current Agent Mail members</li><li>choose provider from newest connected/observed session if possible</li><li>copy current member role/charter into slot role/charter</li><li>set launch mode to provider default</li></ul><h3 id="launch-planning" tabindex="-1">Launch Planning <a class="header-anchor" href="#launch-planning" aria-label="Permalink to &quot;Launch Planning&quot;">​</a></h3><ul><li><code>POST /api/v1/agent-teams/presets/{preset_id}/plan-launch</code></li></ul><p>Request options:</p><ul><li><code>slot_ids</code></li><li><code>reuse_existing: true</code></li><li><code>include_disabled: false</code></li></ul><p>Response per slot:</p><ul><li>desired provider/repo/role</li><li>current state</li><li>planned action: <ul><li><code>reuse</code></li><li><code>spawn</code></li><li><code>skip_disabled</code></li><li><code>blocked</code></li></ul></li><li>reason</li><li>matching live session, if any</li></ul><p>The frontend should show this before launching a full preset.</p><h3 id="launch" tabindex="-1">Launch <a class="header-anchor" href="#launch" aria-label="Permalink to &quot;Launch&quot;">​</a></h3><ul><li><code>POST /api/v1/agent-teams/presets/{preset_id}/launch</code></li></ul><p>Request options:</p><ul><li><code>slot_ids</code></li><li><code>reuse_existing: true</code></li><li><code>include_disabled: false</code></li><li><code>confirm_plan_hash</code></li></ul><p>Behavior:</p><ul><li>recompute plan server-side</li><li>if <code>confirm_plan_hash</code> is provided and no longer matches, return 409 with updated plan</li><li>spawn missing slots</li><li>return launch result</li></ul><p>Do not make launch long-running in v1. Spawning tmux sessions should be quick. Registration can remain <code>pending_registration</code> and be refreshed by UI polling.</p><h3 id="external-agent-api-requirements" tabindex="-1">External Agent API Requirements <a class="header-anchor" href="#external-agent-api-requirements" aria-label="Permalink to &quot;External Agent API Requirements&quot;">​</a></h3><p>The Agent Teams API should be usable by external local agents, not only the React UI.</p><p>Requirements:</p><ul><li>all plan/launch responses must be complete JSON documents with no required UI follow-up to understand status</li><li>launch should accept either: <ul><li>a caller-reviewed <code>confirm_plan_hash</code></li><li>or an explicit <code>skip_plan_confirmation: true</code> for single-step local automation</li></ul></li><li>validation errors should return structured details where practical: <ul><li>preset id</li><li>slot id</li><li>field</li><li>error code</li><li>human-readable message</li></ul></li><li>launch result should include enough data for a caller to continue orchestration: <ul><li>preset id/name</li><li>slot id/name</li><li>provider</li><li>repo path</li><li>action/result</li><li>tmux target/session name</li><li>Agent Mail member id if already known</li><li>pending registration marker if not known yet</li></ul></li><li>API behavior should not depend on localStorage, browser-only confirmation state, or frontend-only generated ids</li></ul><p>Security stance for v1:</p><ul><li>keep this as a local Claude Deck API capability</li><li>do not expose a remote access model in this PR</li><li>if Claude Deck later adds API tokens or external-control permissions, Agent Teams launch endpoints should be easy to put behind that policy</li></ul><p>External agent example flow:</p><ol><li><code>GET /api/v1/agent-teams/presets</code></li><li>choose preset by name or id</li><li><code>POST /api/v1/agent-teams/presets/{preset_id}/plan-launch</code></li><li>inspect per-slot plan</li><li><code>POST /api/v1/agent-teams/presets/{preset_id}/launch</code> with <code>confirm_plan_hash</code></li><li>poll Agent Mail team state or use returned tmux targets for follow-up</li></ol><h2 id="launch-planning-logic" tabindex="-1">Launch Planning Logic <a class="header-anchor" href="#launch-planning-logic" aria-label="Permalink to &quot;Launch Planning Logic&quot;">​</a></h2><p>For each enabled slot:</p><ol><li>Validate provider availability.</li><li>Validate Agent Mail install readiness for that provider: <ul><li>Claude Code: MCP installed, hooks installed if context injection is expected</li><li>Codex: MCP installed, hooks installed for prompt-boundary reminders</li></ul></li><li>Discover tmux sessions through Agent Bridge.</li><li>Match live sessions by: <ul><li>provider equality</li><li>normalized cwd/repo root matching slot <code>repo_path</code>/<code>repo_id</code></li></ul></li><li>If match exists and <code>reuse_existing</code>, plan <code>reuse</code>.</li><li>Otherwise plan <code>spawn</code>.</li></ol><p>Matching should be conservative. A false positive is worse than a duplicate because it gives the user the wrong agent.</p><h2 id="spawn-behavior" tabindex="-1">Spawn Behavior <a class="header-anchor" href="#spawn-behavior" aria-label="Permalink to &quot;Spawn Behavior&quot;">​</a></h2><p>Add a lower-level helper so team launch can pass env vars into tmux:</p><ul><li>current <code>spawn_session(provider_id, options)</code> constructs env flags internally only for platform env</li><li>add optional <code>extra_env: dict[str, str]</code> argument or extend <code>SpawnCommandOptions</code></li></ul><p>For each spawned slot, pass:</p><ul><li><code>CLAUDE_DECK_TEAM_PRESET_ID</code></li><li><code>CLAUDE_DECK_TEAM_SLOT_ID</code></li><li><code>CLAUDE_DECK_TEAM_NAME</code></li><li><code>CLAUDE_DECK_TEAM_SLOT_NAME</code></li></ul><p>Bootstrap prompt:</p><ul><li>If slot has explicit <code>bootstrap_prompt</code>, use it.</li><li>Otherwise synthesize: <ul><li>&quot;You are joining Claude Deck team {team_name} as {slot_display_name}. Call <code>deck_whoami</code> now, review your Agent Mail context, then wait for direction.&quot;</li></ul></li></ul><p>Provider-specific placement:</p><ul><li>Codex: append bootstrap prompt as prompt argument for new sessions.</li><li>Claude Code: append bootstrap prompt where current provider supports <code>prompt</code>.</li><li>For resume/fork modes, be conservative. Include prompt only if existing provider behavior supports it safely.</li></ul><h2 id="agent-mail-context-overlay" tabindex="-1">Agent Mail Context Overlay <a class="header-anchor" href="#agent-mail-context-overlay" aria-label="Permalink to &quot;Agent Mail Context Overlay&quot;">​</a></h2><p>MCP shim and hook shim should read:</p><ul><li><code>CLAUDE_DECK_TEAM_PRESET_ID</code></li><li><code>CLAUDE_DECK_TEAM_SLOT_ID</code></li></ul><p>Registration payload additions:</p><ul><li><code>team_preset_id</code></li><li><code>team_slot_id</code></li></ul><p>Agent Mail service behavior:</p><ul><li>store those values on <code>MailAgentSession</code></li><li>when building context for a session/member, if the active session has a slot: <ul><li>include team name</li><li>include slot display name</li><li>include slot role</li><li>include slot charter</li></ul></li><li>do not copy slot role/charter into <code>MailTeamMember.role</code> or <code>MailTeamMember.charter</code></li></ul><p>Context example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Claude Deck Agent Mail]</span></span>\n<span class="line"><span>You are &quot;project-a-api&quot; - repo: project-a-api.</span></span>\n<span class="line"><span>Team preset: Project A</span></span>\n<span class="line"><span>Team slot: Backend owner</span></span>\n<span class="line"><span>Slot role: Backend implementation</span></span>\n<span class="line"><span>Slot charter: Own FastAPI, DB, migrations, and API contracts.</span></span></code></pre></div><p>Open question for implementation:</p><ul><li>Current context builders operate by member id, not specific session id in all paths. The hook path has a session key and can use exact session metadata. The MCP inbox path may only know member id. Prefer preserving exact session metadata in MCP state after registration so context tools can request context for the current session where needed.</li></ul><h2 id="frontend-ux" tabindex="-1">Frontend UX <a class="header-anchor" href="#frontend-ux" aria-label="Permalink to &quot;Frontend UX&quot;">​</a></h2><h3 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><p>Add <code>Agent Teams</code> under Operations.</p><p>Page layout:</p><ul><li>header with <code>New team</code>, <code>Create from Agent Mail</code>, and <code>Refresh</code></li><li>left/list area for presets</li><li>main detail/editor area for selected preset</li><li>launch summary/status area</li></ul><h3 id="preset-list" tabindex="-1">Preset List <a class="header-anchor" href="#preset-list" aria-label="Permalink to &quot;Preset List&quot;">​</a></h3><p>Each preset card/row:</p><ul><li>name</li><li>description</li><li>slot count</li><li>last launched summary if available</li><li>buttons: <ul><li>Launch</li><li>Plan</li><li>Edit</li><li>Duplicate</li><li>Delete/archive</li></ul></li></ul><h3 id="preset-editor" tabindex="-1">Preset Editor <a class="header-anchor" href="#preset-editor" aria-label="Permalink to &quot;Preset Editor&quot;">​</a></h3><p>Fields:</p><ul><li>name</li><li>description</li><li>slots table/list</li></ul><p>Slot controls:</p><ul><li>enabled toggle</li><li>display name</li><li>provider select</li><li>repo path input</li><li>role</li><li>charter</li><li>launch mode</li><li>provider-specific options</li><li>bootstrap prompt</li></ul><p>Use dense operational UI, not marketing-style cards. This is a workspace management tool.</p><h3 id="launch-plan-dialog" tabindex="-1">Launch Plan Dialog <a class="header-anchor" href="#launch-plan-dialog" aria-label="Permalink to &quot;Launch Plan Dialog&quot;">​</a></h3><p>Before launch, show table:</p><ul><li>slot</li><li>provider</li><li>repo</li><li>current state</li><li>planned action</li><li>reason</li></ul><p>Actions:</p><ul><li><code>Launch</code></li><li><code>Cancel</code></li></ul><p>If there are blocked slots, allow launching unblocked slots only after the UI makes that explicit.</p><h3 id="launch-result" tabindex="-1">Launch Result <a class="header-anchor" href="#launch-result" aria-label="Permalink to &quot;Launch Result&quot;">​</a></h3><p>After launch:</p><ul><li>show per-slot result</li><li>show tmux target/session name for spawned/reused sessions</li><li>show failures inline</li><li>offer <code>Open Agent Mail</code> and <code>Open Agent Bridge</code></li></ul><p>Do not auto-switch pages without user action.</p><h2 id="frontend-types" tabindex="-1">Frontend Types <a class="header-anchor" href="#frontend-types" aria-label="Permalink to &quot;Frontend Types&quot;">​</a></h2><p>Add types under <code>frontend/src/features/agent-teams/types.ts</code>:</p><ul><li><code>AgentTeamPreset</code></li><li><code>AgentTeamSlot</code></li><li><code>AgentTeamPresetCreate</code></li><li><code>AgentTeamPresetUpdate</code></li><li><code>AgentTeamLaunchPlan</code></li><li><code>AgentTeamLaunchPlanItem</code></li><li><code>AgentTeamLaunchResult</code></li><li><code>AgentTeamLaunchResultItem</code></li></ul><p>Reuse provider ids and spawn option names from existing Agent Bridge types where practical.</p><h2 id="implementation-tasks" tabindex="-1">Implementation Tasks <a class="header-anchor" href="#implementation-tasks" aria-label="Permalink to &quot;Implementation Tasks&quot;">​</a></h2><h3 id="task-1-backend-models-and-schemas" tabindex="-1">Task 1: Backend Models And Schemas <a class="header-anchor" href="#task-1-backend-models-and-schemas" aria-label="Permalink to &quot;Task 1: Backend Models And Schemas&quot;">​</a></h3><ul><li>Add database models.</li><li>Add Pydantic schemas.</li><li>Add lightweight migration handling in <code>backend/app/database.py</code> consistent with current project style.</li><li>Add tests for table creation and serialization.</li></ul><h3 id="task-2-team-preset-crud-service" tabindex="-1">Task 2: Team Preset CRUD Service <a class="header-anchor" href="#task-2-team-preset-crud-service" aria-label="Permalink to &quot;Task 2: Team Preset CRUD Service&quot;">​</a></h3><ul><li>Implement create/list/get/update/delete/duplicate.</li><li>Validate provider and repo path.</li><li>Derive repo identity.</li><li>Enforce no duplicate enabled repo slots per preset for v1.</li><li>Test validation and CRUD.</li></ul><h3 id="task-3-create-from-agent-mail" tabindex="-1">Task 3: Create From Agent Mail <a class="header-anchor" href="#task-3-create-from-agent-mail" aria-label="Permalink to &quot;Task 3: Create From Agent Mail&quot;">​</a></h3><ul><li>Add service method that snapshots selected/current members into slots.</li><li>Infer provider from newest live session, falling back to <code>codex-cli</code> if Codex is installed or <code>claude-code</code> if Claude Code is installed. If neither is clear, require user selection later.</li><li>Test generated slots.</li></ul><h3 id="task-4-launch-planner" tabindex="-1">Task 4: Launch Planner <a class="header-anchor" href="#task-4-launch-planner" aria-label="Permalink to &quot;Task 4: Launch Planner&quot;">​</a></h3><ul><li>Add plan computation using Agent Bridge discovery and Agent Mail install status.</li><li>Match provider + repo conservatively.</li><li>Return per-slot planned action/reason.</li><li>Return a stable <code>plan_hash</code> suitable for external callers to confirm later launch.</li><li>Test reuse, spawn, disabled, provider unavailable, Agent Mail not configured.</li></ul><h3 id="task-5-launch-execution" tabindex="-1">Task 5: Launch Execution <a class="header-anchor" href="#task-5-launch-execution" aria-label="Permalink to &quot;Task 5: Launch Execution&quot;">​</a></h3><ul><li>Extend Agent Bridge spawn helper to accept extra env.</li><li>Implement launch endpoint.</li><li>Recompute plan before launch.</li><li>Accept confirmed plan hashes without relying on frontend state.</li><li>Support an explicit single-call local automation path for trusted local callers.</li><li>Spawn missing slots.</li><li>Return partial results.</li><li>Test successful spawn, reuse, and partial failure.</li></ul><h3 id="task-6-agent-mail-session-team-context" tabindex="-1">Task 6: Agent Mail Session Team Context <a class="header-anchor" href="#task-6-agent-mail-session-team-context" aria-label="Permalink to &quot;Task 6: Agent Mail Session Team Context&quot;">​</a></h3><ul><li>Add optional team ids to register payload/session model.</li><li>Update MCP shim and hook shim to forward env values.</li><li>Update Agent Mail context building to include slot context.</li><li>Test registration and context injection.</li></ul><h3 id="task-7-frontend-agent-teams-page" tabindex="-1">Task 7: Frontend Agent Teams Page <a class="header-anchor" href="#task-7-frontend-agent-teams-page" aria-label="Permalink to &quot;Task 7: Frontend Agent Teams Page&quot;">​</a></h3><ul><li>Add route and nav item.</li><li>Implement API client.</li><li>Implement preset list/editor.</li><li>Implement create-from-Agent-Mail action.</li><li>Implement launch plan dialog and launch result panel.</li><li>Add loading/error/empty states.</li></ul><h3 id="task-8-documentation" tabindex="-1">Task 8: Documentation <a class="header-anchor" href="#task-8-documentation" aria-label="Permalink to &quot;Task 8: Documentation&quot;">​</a></h3><ul><li>Add feature doc under <code>docs/features/</code>.</li><li>Add short help copy in Agent Teams page.</li><li>Cross-link from Agent Mail help if useful.</li></ul><h3 id="task-9-validation" tabindex="-1">Task 9: Validation <a class="header-anchor" href="#task-9-validation" aria-label="Permalink to &quot;Task 9: Validation&quot;">​</a></h3><p>Backend:</p><ul><li>targeted <code>pytest</code> for agent teams + agent mail registration changes</li><li>existing Agent Mail tests</li><li>Agent Bridge spawn tests</li></ul><p>Frontend:</p><ul><li>targeted eslint for new feature files</li><li><code>npm run build</code></li></ul><p>Manual:</p><ul><li>create preset manually</li><li>create preset from current Agent Mail roster</li><li>plan launch with live matching session</li><li>launch missing Codex slot</li><li>launch missing Claude Code slot if available</li><li>verify Agent Mail context includes team slot</li><li>verify second launch reuses sessions</li></ul><h2 id="testing-plan" tabindex="-1">Testing Plan <a class="header-anchor" href="#testing-plan" aria-label="Permalink to &quot;Testing Plan&quot;">​</a></h2><p>Backend test files:</p><ul><li><code>backend/tests/agent_teams/test_models.py</code></li><li><code>backend/tests/agent_teams/test_api.py</code></li><li><code>backend/tests/agent_teams/test_service.py</code></li><li>extend: <ul><li><code>backend/tests/agent_mail/test_mcp_shim.py</code></li><li><code>backend/tests/agent_mail/test_hooks_api.py</code></li><li><code>backend/tests/test_agent_bridge_spawn.py</code></li></ul></li></ul><p>Key cases:</p><ul><li>CRUD round trip.</li><li>Duplicate enabled repo slot rejected.</li><li>Disabled duplicate allowed or rejected explicitly; choose one and test.</li><li>Create from current Agent Mail members.</li><li>Launch plan reuses live tmux session.</li><li>Launch plan chooses spawn when no match exists.</li><li>Launch plan blocks unavailable provider.</li><li>Launch execution spawns with team env.</li><li>Launch execution returns partial failure when one slot fails.</li><li>Launch execution accepts a valid <code>confirm_plan_hash</code>.</li><li>Launch execution returns 409 with an updated plan when the confirmed plan hash is stale.</li><li>Launch endpoints return enough structured JSON for an external caller to continue orchestration without UI state.</li><li>MCP shim forwards team env on registration.</li><li>Hook shim forwards team env on registration.</li><li>Agent Mail context includes slot role/charter.</li><li>Global MailTeamMember role/charter are not overwritten by launch.</li></ul><p>Frontend:</p><ul><li>Keep tests lightweight if there is no established frontend test harness.</li><li>Rely on TypeScript build and targeted lint.</li><li>Consider component smoke tests only if local patterns exist.</li></ul><h2 id="risks-and-mitigations" tabindex="-1">Risks And Mitigations <a class="header-anchor" href="#risks-and-mitigations" aria-label="Permalink to &quot;Risks And Mitigations&quot;">​</a></h2><h3 id="risk-confusing-team-slot-with-agent-mail-member" tabindex="-1">Risk: Confusing Team Slot With Agent Mail Member <a class="header-anchor" href="#risk-confusing-team-slot-with-agent-mail-member" aria-label="Permalink to &quot;Risk: Confusing Team Slot With Agent Mail Member&quot;">​</a></h3><p>Mitigation:</p><ul><li>UI labels must distinguish repo member from team slot.</li><li>Do not display slot role as if it were global member role.</li></ul><h3 id="risk-duplicate-sessions" tabindex="-1">Risk: Duplicate Sessions <a class="header-anchor" href="#risk-duplicate-sessions" aria-label="Permalink to &quot;Risk: Duplicate Sessions&quot;">​</a></h3><p>Mitigation:</p><ul><li>launch plan defaults to reuse</li><li>conservative matching by provider + repo root</li><li>require explicit user action to spawn anyway later</li></ul><h3 id="risk-same-repo-multi-agent-expectations" tabindex="-1">Risk: Same Repo Multi-Agent Expectations <a class="header-anchor" href="#risk-same-repo-multi-agent-expectations" aria-label="Permalink to &quot;Risk: Same Repo Multi-Agent Expectations&quot;">​</a></h3><p>Mitigation:</p><ul><li>reject duplicate enabled repo slots in v1</li><li>document that Agent Mail is one member per repo</li></ul><h3 id="risk-provider-options-become-too-complex" tabindex="-1">Risk: Provider Options Become Too Complex <a class="header-anchor" href="#risk-provider-options-become-too-complex" aria-label="Permalink to &quot;Risk: Provider Options Become Too Complex&quot;">​</a></h3><p>Mitigation:</p><ul><li>reuse Agent Bridge option names</li><li>show provider-specific advanced options behind compact sections</li><li>keep default options simple</li></ul><h3 id="risk-registration-race" tabindex="-1">Risk: Registration Race <a class="header-anchor" href="#risk-registration-race" aria-label="Permalink to &quot;Risk: Registration Race&quot;">​</a></h3><p>Mitigation:</p><ul><li>launch returns <code>spawned</code> first</li><li>UI polls Agent Mail and updates to connected/pending registration</li><li>do not block launch endpoint waiting for MCP check-in</li></ul><h3 id="risk-bad-paths-or-unsafe-commands" tabindex="-1">Risk: Bad Paths Or Unsafe Commands <a class="header-anchor" href="#risk-bad-paths-or-unsafe-commands" aria-label="Permalink to &quot;Risk: Bad Paths Or Unsafe Commands&quot;">​</a></h3><p>Mitigation:</p><ul><li>use existing directory validation and provider command builders</li><li>never shell-concatenate user-provided command strings in team service</li><li>keep all spawn execution through Agent Bridge</li></ul><h2 id="rollout-strategy" tabindex="-1">Rollout Strategy <a class="header-anchor" href="#rollout-strategy" aria-label="Permalink to &quot;Rollout Strategy&quot;">​</a></h2><ol><li>Ship backend CRUD + launch planner first.</li><li>Add launch execution and env propagation.</li><li>Add UI.</li><li>Validate with Codex tmux sessions first, because current Agent Mail wakeability is strongest there.</li><li>Validate Claude Code if installed and configured.</li><li>Open PR with issue #189 linked.</li></ol><h2 id="pr-scope" tabindex="-1">PR Scope <a class="header-anchor" href="#pr-scope" aria-label="Permalink to &quot;PR Scope&quot;">​</a></h2><p>This is large but still a single coherent PR if kept disciplined:</p><ul><li>new Agent Teams backend service/API</li><li>minimal DB model additions</li><li>Agent Bridge spawn env support</li><li>Agent Mail session team context support</li><li>new Agent Teams frontend page</li><li>docs/tests</li></ul><p>Do not include:</p><ul><li>non-tmux remote control</li><li>scheduler</li><li>cross-machine support</li><li>multi-member-per-repo mail identity</li><li>large visual redesign of Agent Mail or Agent Bridge</li></ul><h2 id="open-questions-before-implementation" tabindex="-1">Open Questions Before Implementation <a class="header-anchor" href="#open-questions-before-implementation" aria-label="Permalink to &quot;Open Questions Before Implementation&quot;">​</a></h2><ol><li>Should v1 hard-reject duplicate enabled repo slots, or allow them with a shared-inbox warning? <ul><li>Recommendation: hard-reject for v1.</li></ul></li><li>Should launch history be persisted? <ul><li>Recommendation: persist lightweight launch/items if implementation stays simple.</li></ul></li><li>Should Agent Teams live as its own nav item or inside Agent Mail? <ul><li>Recommendation: own nav item under Operations. It is launch orchestration, not messaging.</li></ul></li><li>Should create-from-Agent-Mail include offline members by default? <ul><li>Recommendation: include all selected members, but default selection should favor connected/observed members.</li></ul></li><li>Should launch immediately after plan or require a confirmation dialog? <ul><li>Recommendation: require plan confirmation for full team launch; single-slot launch can show a compact confirm.</li></ul></li></ol>',269)])])}const m=a(o,[["render",n]]);export{h as __pageData,m as default};
